    content: var(--tw-content);
    width: 137px !important;
  }
}
.before\:content-\[\"probe\"\] {
  &::before {
    --tw-content: "probe";
    content: var(--tw-content);
  }
}
.after\:content-\[attr\(data-label\)\] {
  &::after {
    --tw-content: attr(data-label);
    content: var(--tw-content);
  }
}
.after\:content-none {
  &::after {
    content: var(--tw-content);
    --tw-content: none;
    content: none;
  }
}
.before\:hover\:content-\[\"probe\"\] {
  &::before {
    content: var(--tw-content);
    &:hover {
      @media (hover: hover) {
        --tw-content: "probe";
        content: var(--tw-content);
      }
    }
  }
}
